using System.Net;
using System.Text;
using System.Text.Json;

namespace CodexUsageMonitor;

// Headless, isolated rc.4 tests. They exercise shipped parsers and state transitions,
// never fetch X, never start a Codex producer, and never show a desktop window.
internal static class Rc4FieldTrialTests
{
 static readonly DateTimeOffset Now=DateTimeOffset.Parse("2026-09-11T12:00:00Z");
 public static void Run(string[] args)
 {
  int pos=Array.IndexOf(args,"--test-root");string root=Path.GetFullPath(args[pos+1]);Directory.CreateDirectory(root);
  var results=new List<object>();int failed=0;
  void Assert(bool value,string message="assertion"){if(!value)throw new InvalidOperationException(message);}
  void Check(string id,Action action){try{action();results.Add(new{id,result="PASS",classification="SYNTHETIC_PRODUCTION_PATH"});}catch(Exception e){failed++;results.Add(new{id,result="FAIL",classification="SYNTHETIC_PRODUCTION_PATH",error=e.GetType().Name+": "+e.Message});}}
  Announcement One(string source,string payload){var definition=ResetRadar.Sources.Single(x=>x.Id==source);var values=Rc4Radar.Parse(definition,payload,Now,out _);Assert(values.Count==1,source+" expected one event, got "+values.Count);return values.Single();}
  Announcement Watch(string id)=>One("team-codex-reset",TeamHtml(id,"When I say excellent service for existing Codex users, that includes the occasional reset."));
  Announcement Incoming(string id)=>One("team-codex-reset",TeamHtml(id,"Codex global reset will be applied tomorrow around 6 PM PT for all paid plans."));

  Check("T01 rc.3 quota core smoke",()=>{var rows=R004Tests.Rows(100,99);var calc=DailyUsageCalculator.Calculate(rows,TimeZoneInfo.Local,rows[0].observed_at_utc.AddMinutes(-1),rows[1].observed_at_utc.AddMinutes(1));Assert(calc.Days.Sum(x=>x.observed_drawdown_pp??0)==1);});
  Check("T02 no signal no alert",()=>{using var radar=new ResetRadar(Path.Combine(root,"t02"));Assert(radar.Unread==null&&radar.AlertLevel=="NONE");});
  Check("T03 team vague hint WATCH",()=>{var a=Watch("2000000000000000003");Assert(a.SignalLevel=="WATCH"&&a.ResetUtc==null);using var radar=new ResetRadar(Path.Combine(root,"t03"));radar.Apply([a],Now);Assert(radar.AlertLevel=="WATCH");});
  Check("T04 explicit team reset tomorrow INCOMING",()=>{var a=Incoming("2000000000000000004");Assert(a.SignalLevel=="INCOMING"&&a.Phase=="PLANNED"&&a.Effect=="AUTOMATIC_QUOTA_RESET"&&a.ResetUtc>Now);});
  Check("T05 official OpenAI reset incoming",()=>{var a=One("openai-release-notes-rss",OfficialHtml("official-incoming","Codex global reset for all paid plans will begin tomorrow around 6 PM PT."));Assert(a.SourceClass=="OFFICIAL_OPENAI"&&a.SignalLevel=="INCOMING"&&a.Phase=="PLANNED");});
  Check("T06 banked credit is separate",()=>{var a=One("openai-release-notes-rss",OfficialHtml("credit","One Codex banked reset credit for paid plans will be provided tomorrow around 6 PM PT."));Assert(a.Effect=="BANKED_CREDIT_GRANT"&&a.SignalLevel=="NONE"&&a.Phase=="PLANNED");});
  Check("T07 forecast only has no alert",()=>{var values=Rc4Radar.Parse(ResetRadar.Sources.Single(x=>x.Id=="team-codex-reset"),TeamHtml("2000000000000000007","An 87% forecast says a Codex reset might happen."),Now,out _);Assert(values.Count==0);});
  Check("T08 unrelated news has no alert",()=>{var values=Rc4Radar.Parse(ResetRadar.Sources.Single(x=>x.Id=="team-codex-reset"),TeamHtml("2000000000000000008","Codex Spark retirement details are available."),Now,out _);Assert(values.Count==0);});
  Check("T09 same original through two relays deduplicates",()=>{string id="2000000000000000009";var a=Watch(id);var b=One("team-modelyard-rss",TeamFeed(id,"When I say excellent service for existing Codex users, that includes the occasional reset."));using var radar=new ResetRadar(Path.Combine(root,"t09"));radar.Apply([a,b],Now);var item=radar.Snapshot().Events.Single();Assert(item.CanonicalOriginalId=="x:"+id&&(item.EvidenceSources?.Select(x=>x.SourceId).Distinct().Count()??0)>=3);});
  Check("T10 minor relay edit does not re-alert",()=>{string id="2000000000000000010";using var radar=new ResetRadar(Path.Combine(root,"t10"));var first=Watch(id);radar.Apply([first],Now);radar.Read(first.EventId);var stamp=radar.Snapshot().Events.Single().ReadAt;var minor=One("team-modelyard-rss",TeamFeed(id,"When I say excellent service for existing Codex users, that includes the occasional reset for existing accounts."));radar.Apply([minor],Now.AddMinutes(1));Assert(radar.Unread==null&&radar.Snapshot().Events.Single().ReadAt==stamp);});
  Check("T11 explicit time is major unread revision",()=>{string id="2000000000000000011";using var radar=new ResetRadar(Path.Combine(root,"t11"));var first=Watch(id);radar.Apply([first],Now);radar.Read(first.EventId);var incoming=One("team-modelyard-rss",TeamFeed(id,"Codex global reset will be applied tomorrow around 6 PM PT for all paid plans."));radar.Apply([incoming],Now.AddMinutes(1));var state=radar.Snapshot();Assert(radar.Unread?.SignalLevel=="INCOMING"&&state.Transitions.Any(x=>x.FromSignal=="WATCH"&&x.ToSignal=="INCOMING"));Assert(state.SignalHistory.Count==2&&state.SignalHistory[0].SignalLevel=="WATCH"&&state.SignalHistory[1].SignalLevel=="INCOMING"&&state.SignalHistory[0].Timestamp==Now&&state.SignalHistory[1].Timestamp==Now.AddMinutes(1)&&state.SignalHistory[0].PublishedAt!=null&&state.SignalHistory[0].ReadAt!=null&&state.SignalHistory[1].ReadAt==null&&state.SignalHistory.Select(x=>x.ContentHash).Distinct().Count()==2);});
  Check("T12 original URL is preferred",()=>{var a=Incoming("2000000000000000012");Assert(Rc4Radar.PreferredUrl(a)=="https://x.com/thsottiaux/status/2000000000000000012"&&a.RelayUrl=="https://codex-reset.com/tibo");});
  Check("T13 relay event is labeled",()=>{var a=Watch("2000000000000000013");Assert(Rc4Radar.SourceLabel(a,"en-US").Contains("community relay")&&Rc4Radar.SourceLabel(a,"zh-TW").Contains("社群轉送"));});
  Check("T14 Status reset is supporting context",()=>{var a=One("openai-status-rss",Feed("status-reset","Investigating unexpected usage limit resets affecting Codex."));Assert(a.SignalLevel=="SUPPORTING_CONTEXT"&&!Rc4Radar.IsAlert(a));});
  Check("T15 Help 403 is isolated",()=>{using var radar=new ResetRadar(Path.Combine(root,"t15"),new SourceHandler(request=>request.RequestUri!.DnsSafeHost=="help.openai.com"?new(HttpStatusCode.Forbidden):Healthy(request)));radar.Poll(true,CancellationToken.None).GetAwaiter().GetResult();var state=radar.Snapshot();Assert(state.Sources.Count==ResetRadar.Sources.Length&&state.Sources.Count(x=>x.Status=="DEGRADED")==1&&state.Sources.Count(x=>x.Status=="HEALTHY")==ResetRadar.Sources.Length-1);});
  Check("T16 one relay 403 is isolated",()=>{using var radar=new ResetRadar(Path.Combine(root,"t16"),new SourceHandler(request=>request.RequestUri!.DnsSafeHost=="codex-reset.com"?new(HttpStatusCode.Forbidden):Healthy(request)));radar.Poll(true,CancellationToken.None).GetAwaiter().GetResult();Assert(radar.Snapshot().Sources.Single(x=>x.Id=="team-codex-reset").Status=="DEGRADED"&&radar.Snapshot().Sources.Where(x=>x.Id!="team-codex-reset").All(x=>x.Status=="HEALTHY"));});
  Check("T17 all Radar offline leaves quota core intact",()=>{using var service=new MonitorService(Path.Combine(root,"t17-service"));var snapshot=new Snapshot(Now,Now,0,"SYNTHETIC","STABLE_SCOPE","SYNTHETIC","0.153.4",[new("codex","Codex","primary",10080,50,Now.AddDays(7).ToUnixTimeSeconds(),"VALID","pro",null,null,null,"")],2,[]);service.MainClock.Observe(snapshot,service.Monotonic);using var radar=new ResetRadar(Path.Combine(root,"t17-radar"),new SourceHandler(_=>throw new HttpRequestException("synthetic offline")));radar.Poll(true,CancellationToken.None).GetAwaiter().GetResult();Assert(radar.FailedSourceCount==ResetRadar.Sources.Length&&service.MainClock.Value?.Remaining==50&&!service.MainClock.Failed);});
  Check("T18 source health UI semantics",()=>{var uiNow=DateTimeOffset.UtcNow;string dir=Path.Combine(root,"t18");AtomicJson.Save(Path.Combine(dir,"reset_radar.json"),new RadarState{Sources=ResetRadar.Sources.Select(x=>new SourceStatus(x.Id,x.Url,"HEALTHY",uiNow,uiNow,uiNow.AddMinutes(15),HttpStatus:200,SourceClass:x.SourceClass,DisplayName:x.DisplayName,Adapter:x.Adapter)).ToList()});using var service=new MonitorService(dir);using var page=new ResetInfoForm(service,null);string text=string.Join("\n",page.AllControls().Select(x=>x.Text));Assert(page.AllControls().OfType<RadarCoverageView>().Single().Summary.Contains("6 / 6")&&text.Contains(L.T("Radar.SourcesHeading"))&&page.AllControls().OfType<Button>().Any(x=>x.Text==L.T("Radar.CheckNow")));});
  Check("T19 English and zh-TW card",()=>{string original=L.Language;try{foreach(var language in new[]{"en-US","zh-TW"}){L.SetLanguage(language);using var service=new MonitorService(Path.Combine(root,"t19-"+language));var a=Incoming("2000000000000000019");service.Radar.Apply([a],Now);using var page=new ResetInfoForm(service,service.Radar.Unread);string text=string.Join("\n",page.AllControls().Select(x=>x.Text));Assert(text.Contains(L.T("Radar.BadgeIncoming"))&&text.Contains(L.T("Radar.OpenOriginal"))&&!text.Contains("Radar."));}}finally{L.SetLanguage(original);}});
  Check("T20 WATCH and INCOMING colors",()=>{using var watchService=new MonitorService(Path.Combine(root,"t20-watch"));var watch=Watch("2000000000000000020");watchService.Radar.Apply([watch],Now);using var watchPage=new ResetInfoForm(watchService,watchService.Radar.Unread);Assert(watchPage.AllControls().OfType<RadarAccentPanel>().Single().Accent==Theme.Warning);using var incomingService=new MonitorService(Path.Combine(root,"t20-incoming"));var incoming=Incoming("2000000000000000021");incomingService.Radar.Apply([incoming],Now);using var incomingPage=new ResetInfoForm(incomingService,incomingService.Radar.Unread);Assert(incomingPage.AllControls().OfType<RadarAccentPanel>().Single().Accent==Theme.ResetAlert);});
  Check("T21 Compact geometry unchanged",()=>{using var service=new MonitorService(Path.Combine(root,"t21"));using var overlay=new OverlayForm(service,true);service.Settings.Compact=true;overlay.TestScale=1;overlay.Render();Assert(overlay.ClientSize==new Size(156,88)&&overlay.ModeHit==new Rectangle(0,62,24,24)&&overlay.RadarHit==new Rectangle(132,0,24,24));});
  Check("T22 Standard geometry unchanged",()=>{using var service=new MonitorService(Path.Combine(root,"t22"));using var overlay=new OverlayForm(service,true);service.Settings.Compact=false;overlay.TestScale=1;overlay.Render();Assert(overlay.ClientSize==new Size(330,84)&&overlay.ModeHit==new Rectangle(306,56,24,24)&&overlay.RadarHit==new Rectangle(306,0,24,24));});
  Check("T23 Log evidence sections",()=>{string dir=Path.Combine(root,"t23");AtomicJson.Save(Path.Combine(dir,"reset_radar.json"),new RadarState{SourceChecks=[new(Now,"source-check","OFFICIAL_OPENAI","DEGRADED",3,403,"body-hash",Now.AddMinutes(-5),Now.AddMinutes(15),"HTTP_403")]});using var service=new MonitorService(dir);var a=Incoming("2000000000000000023");service.Radar.Apply([a],Now);string file=ReportExporter.Export(service,new(Now.AddDays(-1),Now.AddDays(1)),false,CancellationToken.None,Path.Combine(dir,"field-trial.log"),"en-US");string text=File.ReadAllText(file);foreach(var name in new[]{"RADAR_SOURCE_HEALTH","RADAR_SIGNALS","RADAR_TRANSITIONS","RESET_FIELD_TRIAL_TIMELINE","LOCAL_QUOTA_AROUND_SIGNAL","CORRELATION","EVIDENCE_LIMITATIONS"})Assert(text.Contains("\"section\":\""+name+"\""),name);Assert(text.Contains("what remains unknown",StringComparison.OrdinalIgnoreCase)&&text.Contains("\"candidate_count\":3")&&text.Contains("\"http_status\":403")&&text.Contains("\"body_hash\":\"body-hash\"")&&text.Contains("\"last_success\"")&&text.Contains("\"next_check\""));});
  Check("T24 exported evidence privacy",()=>{string dir=Path.Combine(root,"t24");using var service=new MonitorService(dir);var a=Incoming("2000000000000000024") with{OriginalQuote="contact person@example.com token=secret-value",OriginalSourceUrl="https://x.com/thsottiaux/status/2000000000000000024?token=secret-value",RelayUrl="https://codex-reset.com/tibo?person=user@example.com"};service.Radar.Apply([a],Now);string file=ReportExporter.Export(service,new(Now.AddDays(-1),Now.AddDays(1)),false,CancellationToken.None,Path.Combine(dir,"privacy.log"),"en-US");string text=File.ReadAllText(file);Assert(!text.Contains("person@example.com")&&!text.Contains("secret-value")&&!text.Contains("user@example.com"));});
  Check("T25 no X background source",()=>{Assert(ResetRadar.Sources.All(x=>!new Uri(x.Url).DnsSafeHost.EndsWith("x.com",StringComparison.OrdinalIgnoreCase)));});
  Check("T26 requests have no credentials or browser automation",()=>{var seen=new List<string>();using var radar=new ResetRadar(Path.Combine(root,"t26"),new SourceHandler(request=>{Assert(request.Headers.Authorization==null&&!request.Headers.Contains("Cookie"));Assert(request.RequestUri!.DnsSafeHost is not ("x.com" or "www.x.com"));seen.Add(request.RequestUri.AbsoluteUri);return Healthy(request);}));radar.Poll(true,CancellationToken.None).GetAwaiter().GetResult();Assert(seen.Count==ResetRadar.Sources.Length);});
  Check("T27 all forecast wording is excluded",()=>{foreach(var quote in new[]{"An 87% chance says Codex reset will land tomorrow.","A forecast says a possible Codex reset may happen."}){var values=Rc4Radar.Parse(ResetRadar.Sources.Single(x=>x.Id=="team-codex-reset"),TeamHtml("2000000000000000027",quote),Now,out _);Assert(values.Count==0,quote);}});
  Check("T28 official documentation is not INCOMING",()=>{var values=Rc4Radar.Parse(ResetRadar.Sources.Single(x=>x.Id=="openai-release-notes-rss"),OfficialHtml("documentation","Codex global reset documentation is available today."),Now,out _);Assert(values.Count==1&&values.Single().SignalLevel=="NONE");});
  Check("T29 coverage uses all current configured health",()=>{var degraded=ResetRadar.Sources.Select(x=>new SourceStatus(x.Id,x.Url,"DEGRADED",Now,Now.AddMinutes(-1),Now.AddMinutes(15),1,403,SourceClass:x.SourceClass,DisplayName:x.DisplayName,Adapter:x.Adapter)).ToList();var state=new RadarState{Sources=degraded};Assert(Rc4Radar.Coverage(state,true,Now)=="OFF");state.Sources[0]=state.Sources[0] with{Status="HEALTHY",Failures=0,HttpStatus=200,LastSuccess=Now};Assert(Rc4Radar.Coverage(state,true,Now)=="LIMITED");state.Sources=[state.Sources[0]];Assert(Rc4Radar.Coverage(state,true,Now)!="GOOD");});
  Check("T30 stale relay cannot downgrade or re-alert",()=>{string id="2000000000000000030";using var radar=new ResetRadar(Path.Combine(root,"t30"));var watch=Watch(id);radar.Apply([watch],Now);radar.Read(watch.EventId);var incoming=One("team-modelyard-rss",TeamFeed(id,"Codex global reset will be applied tomorrow around 6 PM PT for all paid plans."));radar.Apply([incoming],Now.AddMinutes(1));radar.Read(radar.Snapshot().Events.Single().EventId);var read=radar.Snapshot().Events.Single().ReadAt;radar.Apply([watch],Now.AddMinutes(2));radar.Apply([incoming],Now.AddMinutes(3));radar.Apply([watch],Now.AddMinutes(4));var state=radar.Snapshot();Assert(state.Events.Single().SignalLevel=="INCOMING"&&state.Events.Single().ResetUtc!=null&&state.Events.Single().ReadAt==read&&radar.Unread==null&&state.Transitions.Count==1&&state.SignalHistory.Count==2);});
  Check("T31 96h evidence survives and unknown banked stays null",()=>{string dir=Path.Combine(root,"t31");using var service=new MonitorService(dir);List<UsageSample> Pair(DateTimeOffset at,string prefix,decimal before,decimal after){var seed=R004Tests.Rows(before,after);var reset=at.AddDays(7);return [seed[0] with{sample_id=prefix+"-a",poll_id=prefix+"-a",observed_at_utc=at,observed_at_local=at,reset_at_utc=reset,reset_at_unix_seconds=reset.ToUnixTimeSeconds(),reset_credits_available_count=null},seed[1] with{sample_id=prefix+"-b",poll_id=prefix+"-b",observed_at_utc=at.AddMinutes(1),observed_at_local=at.AddMinutes(1),reset_at_utc=reset,reset_at_unix_seconds=reset.ToUnixTimeSeconds(),reset_credits_available_count=null}];}service.Radar.Correlate(Pair(Now.AddHours(-80),"old",70,100));service.Radar.Correlate(Pair(Now.AddHours(-1),"new",60,100));Assert(service.Radar.Snapshot().QuotaEvidence.Count==2);string file=ReportExporter.Export(service,new(Now.AddDays(-4),Now.AddDays(1)),false,CancellationToken.None,Path.Combine(dir,"nullable.log"),"en-US");string text=File.ReadAllText(file);Assert(text.Contains("\"BankedBefore\":null")&&text.Contains("\"BankedAfter\":null")&&!text.Contains("\"BankedBefore\":-1"));});
  Check("T32 credit-only movement is evidence not automatic refill",()=>{using var radar=new ResetRadar(Path.Combine(root,"t32"));var rows=R004Tests.Rows(50,50);rows=[rows[0] with{sample_id="credit-a",reset_credits_available_count=2},rows[1] with{sample_id="credit-b",reset_credits_available_count=3}];radar.Correlate(rows);var state=radar.Snapshot();Assert(state.Correlations.Single().Classification=="BANKED_CREDIT_MOVEMENT"&&state.Correlations.Single().Correlation!="PROBABLE"&&state.Correlations.Single().Cause=="UNKNOWN"&&state.QuotaEvidence.Single().BankedBefore==2&&state.QuotaEvidence.Single().BankedAfter==3);});
  Check("T33 Release Notes uses verified HTML fallback",()=>{var source=ResetRadar.Sources.Single(x=>x.Id=="openai-release-notes-rss");Assert(source.Url=="https://openai.com/products/release-notes/"&&source.Adapter=="LEGACY_HTML");var a=One(source.Id,OfficialHtml("fallback","Codex global reset for all paid plans will begin tomorrow around 6 PM PT."));Assert(a.SignalLevel=="INCOMING");});
