  Check("T35 partial signal history export keeps every current revision",()=>{string dir=Path.Combine(root,"t35");var a=Watch("2000000000000000036");var b=Incoming("2000000000000000037");var h=new RadarSignalEvidence(Now,a.EventId,a.RevisionId,a.SignalLevel,a.Phase,a.Effect,a.Scope,a.ResetUtc,a.TimeQuality,a.PublishedAt,Now,a.Source,a.SourceClass,a.OriginalSourceUrl,a.RelayUrl,a.OriginalQuote,a.ContentHash,a.SignalReason);AtomicJson.Save(Path.Combine(dir,"reset_radar.json"),new RadarState{Events=[a,b],SignalHistory=[h]});using var service=new MonitorService(dir);string file=ReportExporter.Export(service,new(Now.AddDays(-1),Now.AddDays(1)),false,CancellationToken.None,Path.Combine(dir,"signals.log"),"en-US");string text=File.ReadAllText(file);Assert(text.Contains(a.ContentHash)&&text.Contains(b.ContentHash)&&text.Contains("\"PublishedAt\"")&&text.Contains("\"ReadAt\""));});
