  Check("T42 matching announcement cannot promote unknown banked baseline",()=>{using var radar=new ResetRadar(Path.Combine(root,"t42"));var rows=R004Tests.Rows(50,80);var at=rows[1].observed_at_utc;var future=at.AddDays(7);rows=[rows[0] with{sample_id="unknown-banked-a",reset_at_utc=future,reset_at_unix_seconds=future.ToUnixTimeSeconds(),reset_credits_available_count=null},rows[1] with{sample_id="unknown-banked-b",reset_at_utc=future,reset_at_unix_seconds=future.ToUnixTimeSeconds(),reset_credits_available_count=2}];var announcement=Incoming("2000000000000000042") with{ResetUtc=at,Scope="PAID",Eligibility="AS_ANNOUNCED"};radar.Apply([announcement],at.AddMinutes(-1));radar.Correlate(rows);var result=radar.Snapshot().Correlations.Single();Assert(result.Classification=="INCONCLUSIVE"&&result.LocalObservation=="NOT_COMPARABLE"&&result.Correlation!="PROBABLE"&&result.Cause=="UNKNOWN");});
  Check("T43 team clock plus reset documentation is not an action",()=>{string body="At 6 PM PT, Codex reset documentation will be available.";var values=Rc4Radar.Parse(ResetRadar.Sources.Single(x=>x.Id=="team-codex-reset"),TeamHtml("2000000000000000043",body),Now,out _);Assert(values.Count==0);});
  Check("T44 latest configured source controls UI and export health",()=>{var uiNow=DateTimeOffset.UtcNow;string dir=Path.Combine(root,"t44");var rows=ResetRadar.Sources.Select(x=>new SourceStatus(x.Id,x.Url,"HEALTHY",uiNow.AddMinutes(-10),uiNow.AddMinutes(-10),uiNow.AddMinutes(5),HttpStatus:200,SourceClass:x.SourceClass,DisplayName:x.DisplayName,Adapter:x.Adapter)).ToList();var target=ResetRadar.Sources[0];rows.Add(new(target.Id,target.Url,"DEGRADED",uiNow,uiNow.AddHours(-5),uiNow.AddMinutes(15),Failures:2,HttpStatus:503,Error:"HTTP_503",SourceClass:target.SourceClass,DisplayName:target.DisplayName,Adapter:target.Adapter));rows.Add(new("obsolete-source","https://openai.com/old","HEALTHY",uiNow,uiNow,uiNow.AddMinutes(15),HttpStatus:200,SourceClass:"OFFICIAL_OPENAI"));AtomicJson.Save(Path.Combine(dir,"reset_radar.json"),new RadarState{Sources=rows});using var service=new MonitorService(dir);var state=service.Radar.Snapshot();Assert(Rc4Radar.LatestConfiguredSources(state).Count()==ResetRadar.Sources.Length&&Rc4Radar.HealthyConfiguredCount(state,uiNow)==ResetRadar.Sources.Length-1&&service.Radar.FailedSourceCount==1);using var page=new ResetInfoForm(service,null);string ui=string.Join("\n",page.AllControls().Select(x=>x.Text));Assert(page.AllControls().OfType<RadarCoverageView>().Single().Summary.Contains("5 / 6"));string file=ReportExporter.Export(service,new(Now.AddDays(-1),Now.AddDays(1)),false,CancellationToken.None,Path.Combine(dir,"health.log"),"en-US");string text=File.ReadAllText(file);Assert(text.Contains("\"healthy_sources\":5")&&text.Contains("\"failed_sources\":1")&&!text.Contains("obsolete-source"));});
  Check("T45 production scheduler distinguishes success and retry",()=>{var success=MonitorService.NextPollSchedule(Now,0,90);var retry=MonitorService.NextPollSchedule(Now,2,90);Assert(success.seconds==90&&success.next==Now.AddSeconds(90));Assert(retry.seconds==MonitorService.Backoff(2)&&retry.seconds==180&&retry.next==Now.AddSeconds(180));var normal=OverlayForm.Countdown(Now,true,false,false,0,success.next,"");var failedState=OverlayForm.Countdown(Now,true,false,false,2,retry.next,"NETWORK_ERROR");Assert(normal.text=="90s"&&normal.state=="SCHEDULED"&&failedState.text=="180s ⚠"&&failedState.state=="RETRY");});

  AtomicJson.Save(Path.Combine(root,"rc4-field-trial-tests.json"),new{classification="SYNTHETIC_PRODUCTION_PATH",executed_utc=DateTimeOffset.UtcNow,exe_sha256=ReportExporter.ExeHash(),total=results.Count,failed,results});
  if(failed>0)Environment.ExitCode=1;
 }

 static string TeamHtml(string id,string quote)=>"<ul><li class=\"feed-item\"><p class=\"feed-text\">"+WebUtility.HtmlEncode(quote)+"</p><a href=\"https://x.com/thsottiaux/status/"+id+"\">original</a><a class=\"feed-time\">1h ago</a></li></ul>";
 static string TeamFeed(string id,string quote)=>"<?xml version=\"1.0\"?><rss><channel><item><title>Codex team signal</title><guid>relay-"+id+"</guid><link>https://tibo.modelyard.dev/posts/"+id+"</link><description><![CDATA[Source text: "+quote+" https://x.com/thsottiaux/status/"+id+"]]></description><pubDate>Fri, 11 Sep 2026 11:00:00 GMT</pubDate></item></channel></rss>";
  static string Feed(string id,string body)=>"<?xml version=\"1.0\"?><rss><channel><item><title>Codex update</title><guid>"+id+"</guid><link>https://openai.com/index/"+id+"</link><description><![CDATA["+body+"]]></description><pubDate>Fri, 11 Sep 2026 11:00:00 GMT</pubDate></item></channel></rss>";
  static string OfficialHtml(string id,string body)=>"<article id=\""+id+"\"><header><h2><a href=\"/products/release-notes/#"+id+"\">Codex update</a></h2><time datetime=\"2026-09-11T11:00:00Z\">September 11, 2026</time></header><p>"+WebUtility.HtmlEncode(body)+"</p></article>";
  internal static string HealthyPayload(HttpRequestMessage request){string host=request.RequestUri!.DnsSafeHost;if(host=="codex-reset.com")return TeamHtml("2999999999999999999","Routine Codex improvements only.");if(host=="help.openai.com")return "<article><h1>Codex</h1><p>Routine improvements only.</p></article>";if(host is "openai.com" or "www.openai.com")return OfficialHtml("healthy-openai","Routine Codex improvements only.");return Feed("healthy-"+host.Replace('.','-'),"Routine Codex improvements only.");}
 static HttpResponseMessage Healthy(HttpRequestMessage request)=>new(HttpStatusCode.OK){Content=new StringContent(HealthyPayload(request),Encoding.UTF8,"text/plain")};
 sealed class SourceHandler(Func<HttpRequestMessage,HttpResponseMessage> send):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>Task.FromResult(send(request));}
